"""Art-only action playback; timing and hit windows are design candidates."""
from pathlib import Path
import json,hashlib
from PIL import Image
import numpy as np
from scipy import ndimage
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/zhongli-design-20261011';B=OUT/'batches/20261011-resume'
def main():
 r=json.loads((B/'report.json').read_text());light=[p for p in r['poses'] if p['id'].startswith('light1')]
 action=dict(actionId='zhongli_light1_candidate',state='art-only design candidate; not runtime integrated',tickRate=60,durations=[3,3,2,2,5,6],phases=['持枪准备','转身蓄势','前刺接触','伸展随挥','撤枪','回收（未归母姿）'],frames=[dict(id=p['id'],source=p['source'],optimized=p['optimized'],root=p['landmarks']['root'],scale=p['scale'],landmarks=p['landmarks']) for p in light],combatDesign=dict(startup=6,active=4,recovery=11,events=[dict(tick=6,kind='hit-candidate',hitId='zhongli_light1_candidate_1',damageSegments=1)],box=[40,160,250,55],status='design-only; box not calibrated to spear or simulated'),issues=['六姿均为已有返修图复用。','第2姿背身蓄势到第3姿正面前刺，肩胯转向与握点衔接需复核。','后三姿躯干投影较基准短，不能仅按筛查值重画。','两脚支撑点及腿链为初步人工标记，尚未播放验收。','第6姿仍为宽站持枪，不能声明已回到空手母姿。','本页没有运行正式游戏命中或取消逻辑。'])
 (B/'light1-action-candidate.json').write_text(json.dumps(action,ensure_ascii=False,indent=2))
 html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>钟离轻攻一 · 动作候选</title><style>body{font:16px/1.6 system-ui;background:#edf0f4;color:#263249;margin:auto;max-width:1100px;padding:24px}section{padding:20px;background:white;margin:20px 0;border-radius:8px}canvas{width:100%;background:#dce2e9;image-rendering:pixelated}.dark canvas{background:#242b38}button,select,input{font:inherit}nav{display:flex;gap:12px;flex-wrap:wrap}#timeline{width:100%}li{margin:8px 0}.notice{padding:16px;background:#fff0d1}a{color:#315c98}</style><h1>钟离 · 轻攻一动作候选</h1><p class="notice">复用已有六姿返修图；无装饰闪光、脚下阴影或独立持枪层。60Hz时间轴与判定窗口只是设计候选，未接正式战斗。</p><nav><a href="review.html">原图／初拟合／优化拟合</a><a href="light1-action-candidate.json" download>下载动作卡</a><a href="report.json" download>下载锚点与拟合数据</a></nav><section><nav><button id="play">播放</button><button id="prev">上一姿</button><button id="next">下一姿</button><button id="mirror">整体镜像</button><button id="theme">深浅底</button><label>图像 <select id="mode"><option value="optimized">优化拟合</option><option value="initial">初始拟合</option><option value="source">原图</option></select></label><label><input id="joints" type="checkbox">显示人工腿链</label></nav><canvas id="stage" width="1000" height="460"></canvas><input id="timeline" type="range" min="0" max="20" value="0"><p id="state" aria-live="polite"></p><p>设计窗口：准备6tick → 有效4tick → 恢复11tick。单次候选命中ID；伤害、取消、移动与盒尚待正式逻辑接入。支撑脚根对齐用于审查，不能掩盖步距与重心跳变。</p></section><section><h2>剩余问题</h2><ul id="issues"></ul></section>__DATA__<script>
const data=JSON.parse(document.querySelector('#data').textContent),poses=data.report.poses.filter(p=>p.id.startsWith('light1')),images=new Map(),stage=document.querySelector('#stage'),slider=document.querySelector('#timeline');let tick=0,playing=false,mirrored=false,ready=false,lastTime=0;const boundaries=[];let total=0;for(const d of data.action.durations){boundaries.push(total);total+=d;}
function frameAt(t){let i=0;while(i<5&&t>=boundaries[i+1])i++;return i;}
function draw(){if(!ready)return;const i=frameAt(tick),p=poses[i],mode=document.querySelector('#mode').value,item=mode==='source'?{file:p.source,root:p.landmarks.root,displayScale:p.scale}:p[mode],im=images.get(item.file),c=stage.getContext('2d');c.clearRect(0,0,1000,460);c.save();if(mirrored){c.translate(1000,0);c.scale(-1,1);}c.imageSmoothingEnabled=false;c.strokeStyle='#8190a0';c.beginPath();c.moveTo(0,420);c.lineTo(1000,420);c.stroke();c.drawImage(im,500-item.root[0]*item.displayScale,420-item.root[1]*item.displayScale,im.width*item.displayScale,im.height*item.displayScale);if(document.querySelector('#joints').checked){const lm=p.landmarks;c.strokeStyle='#20a4bb';c.lineWidth=2;for(const side of ['left','right']){c.beginPath();for(const [j,part] of ['Hip','Knee','Ankle'].entries()){const a=lm[side+part],x=500+(a[0]-lm.root[0])*p.scale,y=420+(a[1]-lm.root[1])*p.scale;j?c.lineTo(x,y):c.moveTo(x,y);c.fillStyle='#dc3650';c.fillRect(x-3,y-3,6,6);}c.stroke();}}c.restore();slider.value=tick;document.querySelector('#state').textContent='Tick '+tick+'/20 · 第'+(i+1)+'姿 · '+data.action.phases[i]+' · '+(tick>=6&&tick<10?'设计有效窗口':'设计准备／恢复')+' · '+(p.torsoReviewFlag?'躯干投影需复核':'仍未验收');}
function setFrame(i){playing=false;document.querySelector('#play').textContent='播放';tick=boundaries[(i+6)%6];draw();}
document.querySelector('#prev').onclick=()=>setFrame(frameAt(tick)-1);document.querySelector('#next').onclick=()=>setFrame(frameAt(tick)+1);document.querySelector('#play').onclick=()=>{playing=!playing;lastTime=performance.now();document.querySelector('#play').textContent=playing?'暂停':'播放';};document.querySelector('#mirror').onclick=()=>{mirrored=!mirrored;draw();};document.querySelector('#theme').onclick=()=>document.body.classList.toggle('dark');slider.oninput=()=>{playing=false;document.querySelector('#play').textContent='播放';tick=+slider.value;draw();};document.querySelector('#mode').onchange=draw;document.querySelector('#joints').onchange=draw;
for(const issue of data.action.issues){const li=document.createElement('li');li.textContent=issue;document.querySelector('#issues').append(li);}
(async()=>{await Promise.all([...new Set(poses.flatMap(p=>[p.source,p.initial.file,p.optimized.file]))].map(async f=>{const im=new Image();im.src=f;await im.decode();images.set(f,im);}));ready=true;draw();})().catch(e=>document.querySelector('#state').textContent='素材载入失败：'+e.message);
function loop(now){if(playing&&ready){const steps=Math.floor((now-lastTime)/(1000/60));if(steps>0){tick=(tick+steps)%total;lastTime+=steps*(1000/60);draw();}}requestAnimationFrame(loop);}requestAnimationFrame(loop);
</script></html>'''
 html=html.replace('__DATA__','<script type="application/json" id="data">'+json.dumps(dict(report=r,action=action),ensure_ascii=False).replace('<','\\u003c')+'</script>');(B/'light1-action-review.html').write_text(html)
 inventory=[]
 for file in sorted((OUT/'sources').glob('*.png')):
  im=Image.open(file).convert('RGBA');a=np.asarray(im);labels,n=ndimage.label(a[:,:,3]>=64);sizes=np.bincount(labels.ravel());y,x=np.where(a[:,:,3]>=128);inventory.append(dict(file=str(file.relative_to(OUT)),sha256=hashlib.sha256(file.read_bytes()).hexdigest(),size=list(im.size),transparentFraction=float((a[:,:,3]==0).mean()),components=int((sizes[1:]>1000).sum()),margins=[int(x.min()),int(y.min()),int(im.width-1-x.max()),int(im.height-1-y.max())],accepted=False,note='Alpha与组件数量仅为筛查，不代表动作或比例合格'))
 (B/'source-audit.json').write_text(json.dumps(inventory,ensure_ascii=False,indent=2));print('Action preview + source audit:',len(inventory))
if __name__=='__main__':main()
